    fun relativeTimeString(elapsedSecs: Long): String {
        requireNative()
        val clamped = maxOf(0L, elapsedSecs)
        val raw = orbRelativeTimeBucket(clamped)
        val unit = (raw and 0xFFL).toInt()
        val value = ((raw ushr 8) and 0xFFFF_FFFFL)
        return when (unit) {
